import{_ as i,l as s,o as e,c as l,v as t,p as d,x as r,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"语法制导翻译","description":"","frontmatter":{"title":"语法制导翻译","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/syntax-directed-translation.md","filePath":"cs/syntax-directed-translation.md","lastUpdated":1789023840000}'),h={name:"cs/syntax-directed-translation.md"};function m(A,a,T,_,S,u){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="语法制导翻译" tabindex="-1">语法制导翻译 <a class="header-anchor" href="#语法制导翻译" aria-label="Permalink to &quot;语法制导翻译&quot;">​</a></h1><div class="epigraph"><p>归约（或下降）走到产生式，就执行翻译方案：建结点、查表、或发出中间代码。语法驱动控制流，语义在动作里。</p><footer>—— 据龙书第 5 章语法制导翻译；Aho and Ullman 的翻译方案传统整理</footer></div><p>上一课<a href="/cs/attribute-grammar">属性文法</a>给出方程。缺口是编译器里那份<strong>可执行的方案</strong>：语法制导翻译（SDT）把方程编成与产生式绑定的代码片段。主干<a href="/cs/ir-three-address">三地址</a>是动作的目标之一。本课钉「何时发代码、值存在哪」，不重开 SSA。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>属性方程是数学；SDT 是实现：<code>E → E1 + T { emit(add); E.addr = newtemp(); }</code>。自底向上：动作在右部末尾最自然（S 属性）。要在右部中间用继承值，须改写成标记非终结符或先建树再走第二遍。缺口是<strong>动作放置</strong>，不是再定义加号语义。</p><p>与访问者：先完整 AST 再翻译，等于把 SDT 从分析期推迟。两种都合法；生成器习惯分析期动作，手写前端习惯后遍。</p><h3 id="emit-不是优化" tabindex="-1"><code>emit</code> 不是优化 <a class="header-anchor" href="#emit-不是优化" aria-label="Permalink to &quot;`emit` 不是优化&quot;">​</a></h3><p>此处发出的是忠实 IR。常量折叠可在动作里做，但那是优化课的对象；本课只要求结构对应。不要在 SDT 里做寄存器分配。</p><p><span class="marginnote">龙书把 SDT 与 AG 放在同章。Appel 的教材偏向先树后 IR。本进阶课二者都认：生成器路径 vs 显式 AST 路径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选定 IR（三地址、树 IR）。为每个产生式写动作：叶结点从 <code>yylval</code> 取值；内部结点综合地址或树指针。控制流：<code>if</code> 产生式留下回填洞，或生成带标号的跳转——与后课中端 CFG 衔接，本课只发指令序列。</p>',11)),(e(),d(c,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROD%5B%22%E4%BA%A7%E7%94%9F%E5%BC%8F%22%5D%20--%3E%20ACT%5B%22%E7%BF%BB%E8%AF%91%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20ACT%20--%3E%20IR%5B%22IR%20%2F%20AST%22%5D%0A%20%20ACT%20--%3E%20SYM%5B%22%E7%AC%A6%E5%8F%B7%E8%A1%A8%E5%89%AF%E4%BD%9C%E7%94%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>错误节点：动作应跳过或发 trap，不要当合法加号去折叠。接<a href="/cs/parse-error-recovery">错误恢复</a>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>左递归产生式的 SDT 自然得到左结合的代码序。右递归则反向，要小心临时值寿命。继承属性在 LR 里常用语义栈上的「已分析兄长」。</p><p>宏展开若发生在 SDT 之前，动作看见的已是展开后记号——本课序后段宏课再钉顺序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写指令选择，不引入 φ。后课默认：前端可用 SDT 得到 AST 或线性 IR。下一课：宏——在记号或树上做的另一类「翻译」，卫生问题从这里露出。</p><p>不要把 SDT 当成类型健全性证明；类型规则下一单元。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SDT：产生式绑定动作，驱动翻译。</li><li>S 属性可在 LR 归约时执行；更复杂就先树后遍。</li><li>动作发 IR，不做分配与调度。</li><li>出处：Aho et al., 龙书第 5 章；对照 Appel 的树转 IR。</li></ul>',9))])}const E=i(h,[["render",m]]);export{D as __pageData,E as default};
